{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.OFFLINE_STORE_DETAILED_MAPPING AS select distinct TRIM(RTRIM(REGEXP_SUBSTR(stock_transfer_branchname, \'^[^-]*-[^-]*-[^-]*\', 1, 1), \'-\')) as store_name, city_name as region, state_name as cluster, stock_transfer_branchcode as store_code, group_name3 as party from snitch_db.maplemonk.logicERPnew_get_party_master ; CREATE OR REPLACE TABLE snitch_db.maplemonk.sto_analysis AS WITH final_sto_data AS ( SELECT ORIGIN, TO_DATE(bill_date, \'DD/MM/YYYY\') AS DATE, TO_TIMESTAMP(bill_time, \'DD/MM/YYYY HH12:MI AM\') as time, to_party, from_party, item_quantity, bill_no, order_no, total_quantity, doc_number, net_amount, vouch_code, so_order_no, account_code, sku, item_group_name_1 AS category, item_mrp FROM snitch_db.maplemonk.logic_final_sto WHERE lower(sku) NOT LIKE \'%cb%\' ), final_data_with_store_details AS ( SELECT fsd.*, gs.store_name, gs.cluster, gs.region FROM final_sto_data fsd LEFT JOIN SNITCH_DB.MAPLEMONK.OFFLINE_STORE_DETAILED_MAPPING gs ON fsd.from_party = gs.store_name ) SELECT * FROM final_data_with_store_details; CREATE OR REPLACE TABLE snitch_db.maplemonk.sti_analysis AS WITH final_sti_data AS ( SELECT ORIGIN, bill_date AS DATE, from_party, to_party, item_quantity, bill_no, total_quantity, net_amount, vouch_code, account_code, sku, item_mrp FROM snitch_db.maplemonk.logic_final_sti WHERE lower(sku) NOT LIKE \'%cb%\' ), final_data_with_store_details AS ( SELECT fsd.*, gs.store_name, gs.cluster, gs.region FROM final_sti_data fsd LEFT JOIN snitch_db.maplemonk.offline_store_detailed_mapping gs ON fsd.to_party = gs.store_name ) SELECT * FROM final_data_with_store_details; CREATE OR REPLACE TABLE snitch_db.maplemonk.purchasev_analysis AS WITH final_purchasev_data AS ( SELECT ORIGIN, bill_date AS DATE, from_party, to_party, item_quantity, bill_no, quantity as total_quantity, net_amount, vouch_code, account_code, sku, item_mrp FROM snitch_db.maplemonk.logic_purchase_voucher WHERE lower(sku) NOT LIKE \'%cb%\' ), final_data_with_store_details AS ( SELECT fpd.*, gs.store_name, gs.cluster, gs.region FROM final_purchasev_data fpd LEFT JOIN snitch_db.maplemonk.offline_store_detailed_mapping gs ON fpd.to_party = gs.store_name ) SELECT * FROM final_data_with_store_details; CREATE OR REPLACE TABLE snitch_db.maplemonk.logic_store_inward AS WITH sti_data AS ( SELECT ORIGIN, DATE, from_party, to_party, item_quantity, bill_no, total_quantity, net_amount, vouch_code, account_code, sku, item_mrp, store_name, cluster, region FROM snitch_db.maplemonk.sti_analysis ), purchasev_data AS ( SELECT ORIGIN, DATE, from_party, to_party, item_quantity, bill_no, total_quantity, net_amount, vouch_code, account_code, sku, item_mrp, store_name, cluster, region FROM snitch_db.maplemonk.purchasev_analysis ) SELECT * FROM sti_data UNION ALL SELECT * FROM purchasev_data;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            